@'
import assert from 'node:assert/strict';
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { parseSkillDocument, documentName, documentDescription } from './packages/core/src/domain/skill-document.ts';
const root=resolve('skills/distributed-tracing-design');
const result=parseManifest(readFileSync(resolve(root,'skill.yaml'),'utf8'),{strict:true});
assert.deepEqual(result.issues,[]);
const doc=parseSkillDocument(readFileSync(resolve(root,'SKILL.md'),'utf8'));
assert.equal(documentName(doc),result.manifest.name);
const normalize=s=>s.replace(/\s+/g,' ').trim();
assert.equal(normalize(documentDescription(doc)),normalize(result.manifest.description));
for(const entry of result.manifest.files) assert.ok(existsSync(resolve(root,entry)),entry);
const mdFiles=['SKILL.md',...readdirSync(resolve(root,'references')).filter(f=>f.endsWith('.md')).map(f=>'references/'+f)];
let links=0;
for(const file of mdFiles){
 const absolute=resolve(root,file), content=readFileSync(absolute,'utf8');
 for(const match of content.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const target=match[1]; if(/^[a-z]+:/i.test(target))continue;
  const [path,anchor]=target.split('#'); const resolved=path?resolve(dirname(absolute),path):absolute;
  assert.ok(existsSync(resolved),file+': '+target);
  if(anchor){ const headings=[...readFileSync(resolved,'utf8').matchAll(/^#{1,6}\s+(.+)$/gm)].map(m=>m[1].toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu,'').trim().replace(/\s/g,'-')); assert.ok(headings.includes(anchor),file+': #'+anchor); }
  links++;
 }
}
console.log(JSON.stringify({manifestIssues:result.issues,name:result.manifest.name,version:result.manifest.version,markdownFiles:mdFiles.length,localLinksAndAnchors:links,descriptionEqual:true}));
'@ | node --input-type=module

